(function(){
var ST=window.ST,BA=ST.BA,FV=window.FV,esc=ST.esc,$=ST.$,staff=ST.staff,D=BA.D;if(!staff||!$('app'))return;
var range=6;
var now=new Date();
function months(){var out=[],R=ST.rng(31337);for(var i=5;i>=0;i--){var d=new Date(now.getFullYear(),now.getMonth()-i,1),g=1+(5-i)*.17;out.push({lab:d.toLocaleDateString('en-GB',{month:'short'}),pro:Math.round((310+R()*30)*g)*499,prem:Math.round((38+R()*6)*g)*2400,law:Math.round((150+R()*20)*g)*1650*.2,cur:i===0})}return out}
function live(){var L=ST.ledger().filter(function(p){return p.live&&!p.refunded}),a={pro:0,prem:0};L.forEach(function(p){a[p.kind==='prem'?'prem':'pro']+=p.amt});return a}
function opsStats(){var ex=BA.jget('ba3_exc',{}),open=0,done=0,oldest=0;(window.BA_EXC||[]).forEach(function(r){var s=(ex[r.id]&&ex[r.id].status)||r.status;if(s==='approved')done++;else{open++;oldest=Math.max(oldest,r.waitH||0)}});return {open:open,done:done,oldest:oldest}}
function render(){var M=months(),lv=live(),cur=M[M.length-1];cur.pro+=lv.pro;cur.prem+=lv.prem;
 var tot=function(m){return m.pro+m.prem+m.law},slice=M.slice(-Math.max(1,range)),rev=slice.reduce(function(a,m){return a+tot(m)},0),prev=M.length>range?M.slice(-2*range,-range).reduce(function(a,m){return a+tot(m)},0):0,mom=Math.round((tot(M[M.length-1])/tot(M[M.length-2])-1)*100);
 var users=ST.users(),paying=users.filter(function(u){return u.plan!=='Free'}).length*95,ops=opsStats(),bk=BA.bk(),done=bk.filter(function(b){return b.status==='completed'}).length,tot2=BA.allRaw().length,fvDone=Math.round(tot2*.58)+Object.keys(BA.jget('ba3_fv',{})).length,prem=BA.allRaw().filter(function(p){return p.premium}).length;
 var cityRows=BA.ck.map(function(c){var n=BA.all().filter(function(p){return p.city===c}).length,u=users.filter(function(x){return x.city===c}).length*95,share=u/(users.length*95);return {c:c,lots:n,u:u,rev:Math.round(rev*share)}});
 var summary=['Revenue for the last '+range+' months is '+ST.compact(rev)+(prev?', '+Math.round((rev/prev-1)*100)+'% on the previous '+range+'.':'.'),'Last month grew '+mom+'% over the month before. Pro packs are '+Math.round(slice.reduce(function(a,m){return a+m.pro},0)/rev*100)+'% of revenue, Premium '+Math.round(slice.reduce(function(a,m){return a+m.prem},0)/rev*100)+'% and advocate commission '+Math.round(slice.reduce(function(a,m){return a+m.law},0)/rev*100)+'%.','Maker publishes 75% of properties on its own. '+ops.open+' exceptions are open in the checker queue; '+ops.done+' have been approved.','Field verification covers '+Math.round(fvDone/tot2*100)+'% of live properties. '+done+' advocate consultations have been completed.'];
 $('app').innerHTML=ST.head('Leadership dashboard','One view of growth, revenue, operations and advocates. Figures marked ● are live from this prototype’s own activity; the rest are illustrative.','<div style="display:flex;gap:8px;flex-wrap:wrap"><select id="rg" class="cs" style="color:var(--ink)">'+[[1,'Last month'],[3,'Last 3 months'],[6,'Last 6 months']].map(function(r){return '<option value="'+r[0]+'"'+(range===r[0]?' selected':'')+'>'+r[1]+'</option>'}).join('')+'</select><button class="btn out sm" id="lcsv">Download CSV</button></div>')+
 '<div class="kpis">'+ST.kpi('Revenue',ST.compact(rev),(prev?(rev>=prev?'▲ ':'▼ ')+Math.abs(Math.round((rev/prev-1)*100))+'% vs previous period':'Selected period'))+ST.kpi('Paying customers',ST.num(paying),Math.round(paying/(users.length*95)*100)+'% of registered')+ST.kpi('Maker auto-publish','75%','Target 80%')+ST.kpi('Field verified properties',Math.round(fvDone/tot2*100)+'%',fvDone+' of '+tot2+' ●')+'</div>'+
 '<div class="two" style="gap:18px;align-items:start">'+ST.panel('Revenue by month',ST.bars([M.map(function(m){return m.pro}),M.map(function(m){return m.prem}),M.map(function(m){return m.law})],M.map(function(m){return m.lab}),['#0F766E','#0F1E33','#F2A33A'],520,200)+ST.legend([['Pro packs','#0F766E'],['Premium','#0F1E33'],['Advocate commission','#F2A33A']]))+
 ST.panel('Operations health','<div class="tg"><span>Checker queue, open ●</span><b>'+ops.open+'</b></div><div class="tg"><span>Approved by checkers ●</span><b>'+ops.done+'</b></div><div class="tg"><span>Median time to approve</span><b>6.4 h</b></div><div class="tg"><span>Advocate response, median</span><b>3.1 h</b></div><div class="tg"><span>Consultations completed ●</span><b>'+done+'</b></div><div class="tg" style="border:0"><span>Premium properties live</span><b>'+prem+'</b></div>')+'</div>'+
 FV.leadPanel()+
 ST.panel('By city',ST.table(['City','Live properties','Registered users','Revenue (period)','Share'],cityRows.map(function(r){return '<tr><td><b>'+esc(D.cities[r.c].label)+'</b></td><td>'+r.lots+'</td><td>'+ST.num(r.u)+'</td><td>'+ST.compact(r.rev)+'</td><td>'+Math.round(r.rev/rev*100)+'%</td></tr>'})))+
 ST.panel('Summary for the board','<ul style="margin:0;padding-left:18px;color:var(--ink);line-height:1.7">'+summary.map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+'</ul>','<button class="btn out sm" id="cpy">Copy summary</button>');
 $('rg').onchange=function(){range=+this.value;render()};
 $('cpy').onclick=function(){try{navigator.clipboard.writeText(summary.join('\n'))}catch(e){}BA.toast('Summary copied')};
 $('lcsv').onclick=function(){ST.csv('leadership-revenue.csv',[['Month','Pro packs','Premium','Advocate commission','Total']].concat(M.map(function(m){return [m.lab,m.pro,m.prem,Math.round(m.law),Math.round(tot(m))]})))}}
render();
})();
